import com.cowave.search.domain.search.document.CatalogDocument
import com.cowave.search.outbound_adapter.factory.toIndexResult
import com.cowave.search.outbound_adapter.index.helper.buildBulkRequest
import com.cowave.search.repository.elasticsearch.ElasticsearchTemplate
import com.cowave.shared.domain.dto.IndexResult
import com.cowave.shared.utils.logger
import org.springframework.stereotype.Component
import kotlin.getValue

@Component
class CatalogIndexRepositoryImpl(
    private val esTemplate: ElasticsearchTemplate,
    private val indexName: IndexNameProperties,
) : CatalogIndexRepository {
    private val logger by logger()

    override fun bulk(documents: List<IndexDocument<CatalogDocument>>): IndexResult {
        if (documents.isEmpty()) {
            return IndexResult.empty()
        }

        val bulkRequest = buildBulkRequest(indexName.appCatalog, documents)

        return try {
            esTemplate.bulk<CatalogDocument>(bulkRequest).toIndexResult()
        } catch (e: Exception) {
            logger.error(e) { "색인 실패: ${e.message}" }
            throw e
        }
    }

    companion object {
        private const val INDEX_NAME = "catalog_index"
    }
}

