import com.cowave.shared.utils.logger
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty
import org.springframework.stereotype.Service

@Service
@ConditionalOnProperty(name = ["index.enabled"], havingValue = "true", matchIfMissing = false)
class ProductAssembleService(
    private val cachedProxyApplicationService: CachedProxyApplicationService,

) {
    private val logger by logger()

    fun assemble(documents: List<ChangedData<Product>>): List<IndexDocument<ProductDocument>> {
        val dependencyId = getDependencyId(documents)
        val dependency = cachedProxyApplicationService.fetchDependencies(dependencyId)

        return documents
            .filter { validateDependency(it, dependency) }
            .map {
                try {
                    when (it.op) {
                        Operation.CREATE,
                        Operation.UPDATE -> {
                            it.toIndexDocument(
                                category = dependency.categories[it.afterData?.categoryId]!!,
                                mall = dependency.malls[it.afterData?.mallId]!!,
                                brandProjection = dependency.brands[it.afterData?.brandId],
                                manufacturerProjection = dependency.manufacturers[it.afterData?.manufacturerId],
                            )
                        }
                        Operation.DELETE -> it.toDeleteDocument()
                    }
                } catch (e: Exception) {
                    logger.error(e) { "[Product Assemble] Failed to assemble product document." +
                        " productId=[${it.id}], partition=[${it.partition}], offset=[${it.offset}]"}
                    throw e
                }
            }
    }

    private fun getDependencyId(documents: List<ChangedData<Product>>): DependencyId {
        val categoryIds: MutableSet<Int> = mutableSetOf()
        val brandIds: MutableSet<Long> = mutableSetOf()
        val manufacturerIds: MutableSet<Long> = mutableSetOf()
        val mallIds: MutableSet<Int> = mutableSetOf()

        documents.forEach {
            if (it.shouldFetchCategory) categoryIds.add(it.afterData!!.categoryId)
            if (it.shouldFetchBrand) it.afterData?.brandId?.run { brandIds.add(this) }
            if (it.shouldFetchManufacturer) it.afterData?.manufacturerId?.run { manufacturerIds.add(this) }
            if (it.shouldFetchMall) it.afterData?.mallId?.run { mallIds.add(this) }
        }

        return DependencyId(
            categoryIds = categoryIds,
            brandIds = brandIds,
            manufacturerIds = manufacturerIds,
            mallIds = mallIds,
        )
    }

    private fun validateDependency(document: ChangedData<Product>, dependency: Dependency): Boolean {

        if (document.shouldFetchCategory && dependency.categories[document.afterData!!.categoryId] == null) {
            logger.warn { "[Product Assemble] Skipped to index product. Category not found. categoryId=[${document.afterData!!.categoryId}]" +
                    " productId=[${document.id}], partition=[${document.partition}], offset=[${document.offset}]" }
            return false
        }

        if (document.shouldFetchMall && dependency.malls[document.afterData!!.mallId] == null) {
            logger.warn { "[Product Assemble] Skipped to index product. Manufacturer not found. mallId=[${document.afterData!!.mallId}]" +
                    " productId=[${document.id}], partition=[${document.partition}], offset=[${document.offset}]" }
            return false
        }

        return true
    }
}

